mapper.select:


    c.del_flag = '0'

        and c.record_type = #{recordType}


        and c.scope_type = #{scopeType}


        and c.status = #{status}


        and c.person_id = #{personId}


        and c.title like concat('%', #{title}, '%')


order by c.create_time desc


where c.parent_id = #{commitId} and c.person_id = #{personId}
  and c.record_type = '1' and c.del_flag = '0'
limit 1

select count(1) from jc_edu_commitment
where record_type = '1' and status = '1' and del_flag = '0'

    and parent_id = #{commitId}
